const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=item=>`./assets/inventory/${item.slot==='weapon'?'sword':'charm'}.png`;

export function inventoryMarkup(state,selectedId){
 const selected=state.inventory.find(item=>item.id===selectedId)||state.inventory[0];
 const equipped=item=>state.equipped[item.slot]===item.id;
 const tile=(item,slot=false)=>`<button class="gear-tile ${item.rarity} ${item.slot} ${selected?.id===item.id?'selected':''}" data-select-item="${escape(item.id)}" aria-label="${escape(item.name)}${equipped(item)?', equipped':''}" aria-pressed="${selected?.id===item.id}" title="${escape(item.name)}"><img src="${art(item)}" alt="" draggable="false">${equipped(item)&&!slot?'<span class="gear-equipped">E</span>':''}</button>`;
 const slot=kind=>{const item=state.inventory.find(item=>item.id===state.equipped[kind]);return `<div class="equipment-slot ${kind}"><span>${kind}</span>${item?tile(item,true):'<div class="empty-equipment">Empty</div>'}</div>`;};
 const used=state.inventory.length;
 const cells=Math.max(24,Math.ceil(used/8)*8);
 const current=selected&&state.inventory.find(item=>item.id===state.equipped[selected.slot]);
 const difference=selected?selected.power-(current?.power||0):0;
 return `<div class="inventory-character"><section class="inventory-attributes" aria-label="Character attributes"><h3>Attributes</h3><dl><div><dt>Level</dt><dd>${state.level}</dd></div><div><dt>Vitality</dt><dd>${Math.ceil(state.hp)} <small>/ ${state.maxHp}</small></dd></div><div><dt>Essence</dt><dd>${Math.floor(state.mana)} <small>/ ${state.maxMana}</small></dd></div><div class="stat-divider"><dt>Cleave</dt><dd>${28+state.level*2+state.damageBonus}</dd></div><div><dt>Honing</dt><dd>${state.forgeLevel} <small>/ 3</small></dd></div><div><dt>Draughts</dt><dd>${state.potions} <small>/ 5</small></dd></div></dl><div class="inventory-crowns"><strong>${state.gold}</strong><span>Crowns</span></div></section><section class="equipment-view" aria-label="Equipped gear"><img class="warden-portrait" src="./assets/inventory/warden.png" alt="The Warden in worn armor and a crimson cloak"><span class="warden-label">The Warden</span>${slot('weapon')}${slot('charm')}</section></div><div class="inventory-bag-heading"><h3>Satchel</h3><span>${state.inventory.length} ${state.inventory.length===1?'item':'items'}</span></div><div class="inventory-grid" aria-label="Owned items">${state.inventory.map(item=>tile(item)).join('')}${Array.from({length:cells-used},()=>'<span class="empty-cell" aria-hidden="true"></span>').join('')}</div><section class="inventory-detail ${selected?.rarity||''}" aria-label="Selected item" aria-live="polite">${selected?`<div class="item-detail-copy"><span class="item-rarity">${selected.rarity} ${selected.slot}</span><h3>${escape(selected.name)}</h3><p>${escape(selected.description)}</p><span class="item-bonus">${selected.power?'+'+selected.power+(selected.slot==='weapon'?' cleave damage':' maximum vitality'):'Starting weapon'}${!equipped(selected)&&difference?` <span class="item-comparison ${difference>0?'better':'worse'}">(${difference>0?'+':''}${difference} vs. equipped)</span>`:''}</span></div><button class="inventory-equip" data-equip="${escape(selected.id)}" ${equipped(selected)?'disabled':''}>${equipped(selected)?'Equipped':'Equip'}</button>`:'<p>Your satchel is empty.</p>'}</section><p class="inventory-hint">Select an item to inspect · Collect marked loot with <kbd>F</kbd></p>`;
}
